                float b3 = bs[p * 64 + tx + 48];
                c0_0 += a0 * b0;
                c0_1 += a0 * b1;
                c0_2 += a0 * b2;
                c0_3 += a0 * b3;
                c1_0 += a1 * b0;
                c1_1 += a1 * b1;
                c1_2 += a1 * b2;
                c1_3 += a1 * b3;
                c2_0 += a2 * b0;
                c2_1 += a2 * b1;
                c2_2 += a2 * b2;
                c2_3 += a2 * b3;
                c3_0 += a3 * b0;
