                int idx = tid + 128 * q;
                int mm;
                int kk;
                if (transA == 0) {
                    mm = idx / 16;
                    kk = idx - mm * 16;
                } else {
                    kk = idx / 64;
                    mm = idx - kk * 64;
                }
