    /**
     * Tensor-core GEMM on bf16 operands (CUDA, generated by scripts/codegen/gemm_mma.py gemmMmaBF16 bf16):
     * C[z] = op(A[z]) op(B[z]) with FP32 accumulation, A[z] at z * strideA, B[z] at z * strideB
     * (0 broadcasts), C[z] at z * m * n. One warp per 32x32 block; launch 32-thread groups over
     * ceil(N/32) x (batch * tilesY) groups, tilesY = ceil(M/32). {@code epilogue}: see {@link #store}.
     */
    public static void gemmMmaBF16(KernelContext kc, ShortArray a, ShortArray b, FloatArray c, FloatArray bias, int m, int n, int k, int transA, int transB, int epilogue, int strideA, int strideB, int tilesY) {
        int[] at0 = kc.allocateIntLocalArray(128);
        int[] at1 = kc.allocateIntLocalArray(128);
        int[] bt0 = kc.allocateIntLocalArray(64);
        int[] bt1 = kc.allocateIntLocalArray(64);
        int[] bt2 = kc.allocateIntLocalArray(64);
        int[] bt3 = kc.allocateIntLocalArray(64);
        int lane = kc.localIdx;
        int bz = kc.groupIdy / tilesY;
        int row0 = (kc.groupIdy - bz * tilesY) * 32;
        int col0 = kc.groupIdx * 32;
        int offA = bz * strideA;
        int offB = bz * strideB;
        int offC = bz * m * n;
        float[] acc00 = kc.mmaFragment(0.0f);
        float[] acc01 = kc.mmaFragment(0.0f);
        float[] acc02 = kc.mmaFragment(0.0f);
        float[] acc03 = kc.mmaFragment(0.0f);
        float[] acc10 = kc.mmaFragment(0.0f);
        float[] acc11 = kc.mmaFragment(0.0f);
        float[] acc12 = kc.mmaFragment(0.0f);
        float[] acc13 = kc.mmaFragment(0.0f);
        for (int k0 = 0; k0 < k; k0 += 16) {
            for (int e = lane; e < 128; e += 32) {
                int gr = row0 + 0 + e / 8;
                int ak = k0 + 2 * (e - (e / 8) * 8);
                int lo = 0;
                int hi = 0;
                if (gr < m) {
                    if (ak < k) {
                        lo = transA == 0 ? (a.get(offA + gr * k + ak) & 0xFFFF) : (a.get(offA + ak * m + gr) & 0xFFFF);
                    }
                    if (ak + 1 < k) {
                        hi = transA == 0 ? (a.get(offA + gr * k + ak + 1) & 0xFFFF) : (a.get(offA + (ak + 1) * m + gr) & 0xFFFF);
                    }
                }
                at0[e] = lo | (hi << 16);
            }
            for (int e = lane; e < 128; e += 32) {
                int gr = row0 + 16 + e / 8;
                int ak = k0 + 2 * (e - (e / 8) * 8);
                int lo = 0;
                int hi = 0;
                if (gr < m) {
                    if (ak < k) {
                        lo = transA == 0 ? (a.get(offA + gr * k + ak) & 0xFFFF) : (a.get(offA + ak * m + gr) & 0xFFFF);
                    }
                    if (ak + 1 < k) {
                        hi = transA == 0 ? (a.get(offA + gr * k + ak + 1) & 0xFFFF) : (a.get(offA + (ak + 1) * m + gr) & 0xFFFF);
                    }
                }
                at1[e] = lo | (hi << 16);
            }
            for (int e = lane; e < 64; e += 32) {
                int bk = k0 + e / 4;
                int gc = col0 + 0 + 2 * (e - (e / 4) * 4);
                int lo = 0;
                int hi = 0;
                if (bk < k) {
                    if (gc < n) {
                        lo = transB == 0 ? (b.get(offB + bk * n + gc) & 0xFFFF) : (b.get(offB + gc * k + bk) & 0xFFFF);
                    }
                    if (gc + 1 < n) {
                        hi = transB == 0 ? (b.get(offB + bk * n + gc + 1) & 0xFFFF) : (b.get(offB + (gc + 1) * k + bk) & 0xFFFF);
                    }
                }
                bt0[e] = lo | (hi << 16);
            }
            for (int e = lane; e < 64; e += 32) {
                int bk = k0 + e / 4;
                int gc = col0 + 8 + 2 * (e - (e / 4) * 4);
                int lo = 0;
                int hi = 0;
                if (bk < k) {
                    if (gc < n) {
                        lo = transB == 0 ? (b.get(offB + bk * n + gc) & 0xFFFF) : (b.get(offB + gc * k + bk) & 0xFFFF);
                    }
                    if (gc + 1 < n) {
                        hi = transB == 0 ? (b.get(offB + bk * n + gc + 1) & 0xFFFF) : (b.get(offB + (gc + 1) * k + bk) & 0xFFFF);
                    }
                }
                bt1[e] = lo | (hi << 16);
            }
            for (int e = lane; e < 64; e += 32) {
                int bk = k0 + e / 4;
                int gc = col0 + 16 + 2 * (e - (e / 4) * 4);
                int lo = 0;
                int hi = 0;
                if (bk < k) {
                    if (gc < n) {
                        lo = transB == 0 ? (b.get(offB + bk * n + gc) & 0xFFFF) : (b.get(offB + gc * k + bk) & 0xFFFF);
                    }
                    if (gc + 1 < n) {
                        hi = transB == 0 ? (b.get(offB + bk * n + gc + 1) & 0xFFFF) : (b.get(offB + (gc + 1) * k + bk) & 0xFFFF);
                    }
                }
                bt2[e] = lo | (hi << 16);
            }
            for (int e = lane; e < 64; e += 32) {
                int bk = k0 + e / 4;
                int gc = col0 + 24 + 2 * (e - (e / 4) * 4);
                int lo = 0;
                int hi = 0;
                if (bk < k) {
                    if (gc < n) {
                        lo = transB == 0 ? (b.get(offB + bk * n + gc) & 0xFFFF) : (b.get(offB + gc * k + bk) & 0xFFFF);
                    }
                    if (gc + 1 < n) {
                        hi = transB == 0 ? (b.get(offB + bk * n + gc + 1) & 0xFFFF) : (b.get(offB + (gc + 1) * k + bk) & 0xFFFF);
                    }
                }
                bt3[e] = lo | (hi << 16);
            }
            kc.localBarrier();
            HalfFloat[] fa0 = kc.mmaLoadA(at0, 16);
            HalfFloat[] fa1 = kc.mmaLoadA(at1, 16);
            HalfFloat[] fb0 = kc.mmaLoadB(bt0, 16);
            HalfFloat[] fb1 = kc.mmaLoadB(bt1, 16);
            HalfFloat[] fb2 = kc.mmaLoadB(bt2, 16);
            HalfFloat[] fb3 = kc.mmaLoadB(bt3, 16);
            acc00 = kc.mmaBF16(fa0, fb0, acc00, MMAShape.M16N8K16);
            acc01 = kc.mmaBF16(fa0, fb1, acc01, MMAShape.M16N8K16);
            acc02 = kc.mmaBF16(fa0, fb2, acc02, MMAShape.M16N8K16);
            acc03 = kc.mmaBF16(fa0, fb3, acc03, MMAShape.M16N8K16);
            acc10 = kc.mmaBF16(fa1, fb0, acc10, MMAShape.M16N8K16);
            acc11 = kc.mmaBF16(fa1, fb1, acc11, MMAShape.M16N8K16);
            acc12 = kc.mmaBF16(fa1, fb2, acc12, MMAShape.M16N8K16);
            acc13 = kc.mmaBF16(fa1, fb3, acc13, MMAShape.M16N8K16);
            kc.localBarrier();
        }
        int lr = lane / 4;
        int lc = 2 * (lane - lr * 4);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 0 + lc, acc00[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 0 + lc + 1, acc00[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 0 + lc, acc00[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 0 + lc + 1, acc00[3], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 8 + lc, acc01[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 8 + lc + 1, acc01[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 8 + lc, acc01[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 8 + lc + 1, acc01[3], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 16 + lc, acc02[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 16 + lc + 1, acc02[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 16 + lc, acc02[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 16 + lc + 1, acc02[3], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 24 + lc, acc03[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr, col0 + 24 + lc + 1, acc03[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 24 + lc, acc03[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 0 + lr + 8, col0 + 24 + lc + 1, acc03[3], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 0 + lc, acc10[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 0 + lc + 1, acc10[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 0 + lc, acc10[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 0 + lc + 1, acc10[3], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 8 + lc, acc11[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 8 + lc + 1, acc11[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 8 + lc, acc11[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 8 + lc + 1, acc11[3], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 16 + lc, acc12[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 16 + lc + 1, acc12[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 16 + lc, acc12[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 16 + lc + 1, acc12[3], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 24 + lc, acc13[0], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr, col0 + 24 + lc + 1, acc13[1], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 24 + lc, acc13[2], epilogue);
        storeAt(c, bias, offC, m, n, row0 + 16 + lr + 8, col0 + 24 + lc + 1, acc13[3], epilogue);
    }

    /** Epilogue bit: add {@code bias[col]}. */
    public static final int BIAS = 1;
    /** Epilogue bit: apply ReLU after the bias. */
    public static final int RELU = 2;
    /** Epilogue flag: exact GELU, x * Phi(x), after the bias. */
    public static final int GELU = 4;
    /** Epilogue bit of the batched kernels: add {@code bias[row]} (a 1x1 convolution's channel bias). */
    public static final int ROW_BIAS = 8;
    /**
     * Epilogue flag: tanh-approximated GELU after the bias. Only the FP16-output epilogues
     * (LibraryGlueKernels) take it; the GEMM kernels do not.
     */
    public static final int GELU_TANH = 16;

    /**
     * Writes one output with the fused epilogue. TornadoVM specialises scalar arguments, so the
     * epilogue branches fold away at compile time.
     */
    private static void store(FloatArray c, FloatArray bias, int m, int n, int row, int col, float v, int epilogue) {
        if ((row < m) & (col < n)) {
            float r = v;
            if ((epilogue & BIAS) != 0) {
                r = r + bias.get(col);
            }
            if ((epilogue & RELU) != 0) {
                r = r > 0.0f ? r : 0.0f;
            }
            if ((epilogue & GELU) != 0) {
                r = r * ElementwiseKernels.normalCdf(r);
            }
            c.set(row * n + col, r);
        }
    }

    /** {@link #store} into the matrix that starts at {@code offset}. */
    private static void storeAt(FloatArray c, FloatArray bias, int offset, int m, int n, int row, int col, float v, int epilogue) {
        if ((row < m) & (col < n)) {
            float r = v;
            if ((epilogue & BIAS) != 0) {
                r = r + bias.get(col);
            }
            if ((epilogue & ROW_BIAS) != 0) {
                r = r + bias.get(row);
            }
            if ((epilogue & RELU) != 0) {
                r = r > 0.0f ? r : 0.0f;
            }
            if ((epilogue & GELU) != 0) {
                r = r * ElementwiseKernels.normalCdf(r);
            }
            c.set(offset + row * n + col, r);
        }
    }

    /** Bias and activation over a [rows, cols] matrix in place (the epilogue for kernels that cannot fuse it). */
    public static void biasActivation(KernelContext kc, FloatArray c, FloatArray bias, int rows, int cols, int epilogue) {
        int i = kc.globalIdx;
        if (i < rows * cols) {
            int col = i % cols;
            float r = c.get(i);
            if ((epilogue & BIAS) != 0) {
                r = r + bias.get(col);
            }
            if ((epilogue & RELU) != 0) {
                r = r > 0.0f ? r : 0.0f;
            }
            if ((epilogue & GELU) != 0) {
                r = r * ElementwiseKernels.normalCdf(r);
            }
            c.set(i, r);
        }
    }

    /** Register-blocked GEMM, generated by scripts/codegen/gemm.py gemm64p 64 64 16 4 4: a 16x16 work-group
     * computes a 64x64 block of C, each thread 4x4 outputs. Launch 16x16 groups of threads over
     * ceil(N/64) x ceil(M/64) groups. {@code epilogue}: see {@link #store}. */
    public static void gemm64p(KernelContext kc, FloatArray a, FloatArray b, FloatArray c, FloatArray bias, int m, int n, int k, int transA, int transB, int epilogue) {
        float[] as = kc.allocateFloatLocalArray(1040);
        float[] bs = kc.allocateFloatLocalArray(1040);
        int tx = kc.localIdx;
        int ty = kc.localIdy;
        int tid = ty * 16 + tx;
        int row0 = kc.groupIdy * 64;
        int col0 = kc.groupIdx * 64;
        float c0_0 = 0.0f;
        float c0_1 = 0.0f;
        float c0_2 = 0.0f;
        float c0_3 = 0.0f;
        float c1_0 = 0.0f;
        float c1_1 = 0.0f;
        float c1_2 = 0.0f;
        float c1_3 = 0.0f;
        float c2_0 = 0.0f;
        float c2_1 = 0.0f;
        float c2_2 = 0.0f;
        float c2_3 = 0.0f;
        float c3_0 = 0.0f;
        float c3_1 = 0.0f;
        float c3_2 = 0.0f;
        float c3_3 = 0.0f;
        int tiles = (k + 15) / 16;
        for (int t = 0; t < tiles; t++) {
            int k0 = t * 16;
            for (int q = 0; q < 4; q++) {
                int idx = tid + 256 * q;
                int mm;
                int kk;
                if (transA == 0) {
                    mm = idx / 16;
                    kk = idx - mm * 16;
                } else {
                    kk = idx / 64;
                    mm = idx - kk * 64;
                }
                int gr = row0 + mm;
                int gk = k0 + kk;
                float va = 0.0f;
                if ((gr < m) & (gk < k)) {
                    va = transA == 0 ? a.get(gr * k + gk) : a.get(gk * m + gr);
                }
                as[kk * 65 + mm] = va;
            }
            for (int q = 0; q < 4; q++) {
                int idx = tid + 256 * q;
                int nn;
                int kb;
                if (transB == 0) {
                    kb = idx / 64;
                    nn = idx - kb * 64;
                } else {
                    nn = idx / 16;
                    kb = idx - nn * 16;
                }
                int gc = col0 + nn;
                int gkb = k0 + kb;
                float vb = 0.0f;
                if ((gkb < k) & (gc < n)) {
                    vb = transB == 0 ? b.get(gkb * n + gc) : b.get(gc * k + gkb);
                }
                bs[kb * 65 + nn] = vb;
            }
            kc.localBarrier();
            for (int p = 0; p < 16; p++) {
                float a0 = as[p * 65 + ty + 0];
                float a1 = as[p * 65 + ty + 16];
                float a2 = as[p * 65 + ty + 32];
                float a3 = as[p * 65 + ty + 48];
                float b0 = bs[p * 65 + tx + 0];
                float b1 = bs[p * 65 + tx + 16];
                float b2 = bs[p * 65 + tx + 32];
                float b3 = bs[p * 65 + tx + 48];
                c0_0 += a0 * b0;
                c0_1 += a0 * b1;
                c0_2 += a0 * b2;
                c0_3 += a0 * b3;
                c1_0 += a1 * b0;
                c1_1 += a1 * b1;
                c1_2 += a1 * b2;
                c1_3 += a1 * b3;
                c2_0 += a2 * b0;
                c2_1 += a2 * b1;
                c2_2 += a2 * b2;
                c2_3 += a2 * b3;
                c3_0 += a3 * b0;
                c3_1 += a3 * b1;
                c3_2 += a3 * b2;
                c3_3 += a3 * b3;
            }
            kc.localBarrier();
        }
        int r = row0 + ty;
        int q = col0 + tx;
        store(c, bias, m, n, r + 0, q + 0, c0_0, epilogue);
        store(c, bias, m, n, r + 0, q + 16, c0_1, epilogue);
        store(c, bias, m, n, r + 0, q + 32, c0_2, epilogue);
        store(c, bias, m, n, r + 0, q + 48, c0_3, epilogue);
        store(c, bias, m, n, r + 16, q + 0, c1_0, epilogue);
        store(c, bias, m, n, r + 16, q + 16, c1_1, epilogue);
        store(c, bias, m, n, r + 16, q + 32, c1_2, epilogue);
        store(c, bias, m, n, r + 16, q + 48, c1_3, epilogue);
        store(c, bias, m, n, r + 32, q + 0, c2_0, epilogue);
        store(c, bias, m, n, r + 32, q + 16, c2_1, epilogue);
        store(c, bias, m, n, r + 32, q + 32, c2_2, epilogue);
        store(c, bias, m, n, r + 32, q + 48, c2_3, epilogue);
        store(c, bias, m, n, r + 48, q + 0, c3_0, epilogue);
        store(c, bias, m, n, r + 48, q + 16, c3_1, epilogue);
        store(c, bias, m, n, r + 48, q + 32, c3_2, epilogue);
        store(c, bias, m, n, r + 48, q + 48, c3_3, epilogue);
    }

